      h += '<div class="rec" data-port="' + port + '"><div class="rhead"><b>Port ' + port + '</b><span>' + esc(r.chipName || r.chip || '') + '</span><span>'
        + esc(r.date || 'date unknown') + '</span><span>' + st + (r.error ? ': ' + esc(r.error) : '') + '</span>'
        + (r.clearable ? '<button data-clear="' + port + '">Clear</button>' : '') + '</div><dl>'
        + '<dt>Black</dt><dd class="mono">' + ref(r.black) + '</dd><dt>White</dt><dd class="mono">' + ref(r.white) + '</dd>'
        + '<dt>Exposure</dt><dd class="mono">' + (x ? num(x.gain) + '&times; &middot; ' + ms(num(x.integration_time)) + ' ms' + (x.mode ? ' (' + esc(x.mode) + ')' : '') : 'chip default') + '</dd>'
        + '<dt>Gain steps</dt><dd class="mono">' + (Array.isArray(r.gain_steps) ? r.gain_steps.map((q) => num(q).toFixed(2)).join(' / ') : 'nominal') + '</dd></dl></div>';
